import {modes,modeNames,indiaToday,addDays,validateQuery,searchSampleFares,filterFares,parseTrip,money,durationText,clockText} from './engine.js';
const $=id=>document.getElementById(id);
const paths={all:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h6v6h-6z',flight:'M22 2 9 15 M22 2l-8 20-4-8-8-4Z',train:'M6 3h12a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Z M4 11h16 M9 3v8 M15 3v8 M7 15h1 M16 15h1 M7 19l-2 3 M17 19l2 3',bus:'M5 3h14a2 2 0 0 1 2 2v12H3V5a2 2 0 0 1 2-2Z M3 11h18 M8 3v8 M16 3v8 M6 14h1 M17 14h1 M5 17v4h3v-4 M16 17v4h3v-4',cab:'M4 10l2-6h12l2 6 M3 10h18v8H3Z M5 18v3h3v-3 M16 18v3h3v-3 M6 14h2 M16 14h2'};
const icon=m=>'<svg class="mode-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'+paths[m]+'"/></svg>';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={query:{from:'Bengaluru',to:'Chennai',date:addDays(indiaToday(),1),travellers:1},mode:'all',sort:'price',confirmed:true,budget:0};
let fares=[];
const dialog=$('details');
function syncForm(){for(const key of ['from','to','date','travellers'])$(key).value=state.query[key];$('date').min=indiaToday();}
function filters(overrides={}){return {...state,...overrides}}
function render(){const filtered=filterFares(fares,filters());const eligible=filterFares(fares,filters({mode:'all',sort:'price'}));const cheapest=filtered.reduce((min,f)=>!min||f.total<min.total?f:min,null);
$('route-heading').textContent=state.query.from+' to '+state.query.to;
const date=new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',year:'numeric'}).format(new Date(state.query.date+'T12:00:00'));
$('result-caption').textContent=date+' · '+state.query.travellers+' adult'+(state.query.travellers>1?'s':'')+' · '+filtered.length+' sample options';
$('mode-tabs').innerHTML=modes.map(m=>{const best=eligible.find(f=>m==='all'||f.mode===m);return '<button class="mode-tab '+(state.mode===m?'active':'')+'" data-mode="'+m+'" aria-pressed="'+(state.mode===m)+'"><span class="tab-name">'+icon(m)+modeNames[m]+'</span><span class="tab-price">'+(best?'from '+money(best.total):'No options')+'</span></button>'}).join('');
$('results').innerHTML=filtered.length?filtered.map(f=>'<article class="fare-card '+(f.id===cheapest.id?'cheapest':'')+'">'+(f.id===cheapest.id?'<div class="card-ribbon"><span>LOWEST SAMPLE TOTAL</span><span>All shown fees included</span></div>':'')+'<div class="card-main"><div class="operator"><span class="operator-icon '+f.mode+'">'+icon(f.mode)+'</span><div><strong>'+f.provider+'</strong><small>'+f.service+'</small></div></div><div class="timeline"><div class="time">'+clockText(f.depart)+'<small>'+escape(f.from)+'</small></div><div class="line-time">'+durationText(f.duration)+'<div class="line"></div>'+(f.mode==='flight'?'Nonstop':'Direct')+'</div><div class="time end">'+clockText(f.depart+f.duration)+(f.depart+f.duration>=1440?'<sup style="font-size:10px"> +1</sup>':'')+'<small>'+escape(f.to)+'</small></div></div><div class="price"><strong>'+money(f.total)+'</strong><small>'+(f.mode==='cab'?'whole vehicle':'for '+state.query.travellers+' adult'+(state.query.travellers>1?'s':''))+'</small></div></div><div class="card-bottom"><span class="status '+(f.status==='waitlist'?'waitlist':'')+'">'+(f.status==='waitlist'?'Sample waitlist':'Sample confirmed')+'</span><span class="sample-label">'+(f.mode==='cab'?f.capacity+' passenger seats':'Illustrative fare')+'</span><button class="details-button" data-fare="'+f.id+'">Fare details</button></div></article>').join(''):'<div class="empty"><h3>'+(fares.length?'No options match these filters':'This route is not in the preview yet')+'</h3><p>'+(fares.length?'Try a higher budget, another travel mode, or include waitlisted sample fares.':'Explore Bengaluru–Chennai, Mumbai–Pune, Delhi–Jaipur, or Bengaluru–Hyderabad in either direction.')+'</p>'+(fares.length?'<button class="primary" id="reset-filters">Reset filters</button>':'')+'</div>';
$('insights').innerHTML=modes.filter(m=>m!=='all').map(m=>{const best=eligible.find(f=>f.mode===m);return '<div class="insight-row">'+icon(m)+'<span>'+modeNames[m]+'</span><strong>'+(best?money(best.total):'—')+'</strong></div>'}).join('');
$('confirmed').checked=state.confirmed;$('sort').value=state.sort;
if(![...$('budget').options].some(o=>Number(o.value)===state.budget)){const option=document.createElement('option');option.value=state.budget;option.textContent='Up to '+money(state.budget);$('budget').add(option)}$('budget').value=state.budget;
}
function search(query){validateQuery(query);const next=searchSampleFares(query);state.query={...query};fares=next;syncForm();$('search-error').textContent='';render();return {dataMode:'sample',query:state.query,coverage:'Four sample routes; no live providers',results:filterFares(fares,filters()).map(f=>({id:f.id,mode:f.mode,totalINR:f.total,durationMinutes:f.duration,availability:f.status,isSample:true}))}}
function showDialog(content){$('dialog-content').innerHTML=content;if(!dialog.open)dialog.showModal()}
function showCoverage(){showDialog('<h2>A clear view of our coverage</h2><p class="dialog-subtitle">Farewise is an interactive prototype. All prices, operators, schedules, seats, and fare rules shown are illustrative.</p><ul class="dialog-list"><li><strong>Live provider connections: 0.</strong></li><li>Sample routes: Bengaluru–Chennai, Mumbai–Pune, Delhi–Jaipur, and Bengaluru–Hyderabad, in both directions.</li><li>Flight samples are omitted on Mumbai–Pune.</li><li>Totals cover all selected adults, or one eligible cab. Sample fees are included; station and airport transfers are excluded.</li><li>Dates label your sample journey; they do not retrieve date-specific fares.</li><li>No tickets can be booked, and no price alerts are running.</li></ul><p class="dialog-note">The lowest result means the lowest sample total within your filters. Real comparison requires approved provider access and a fresh price check before booking.</p>')}
function fareDetails(id){const f=fares.find(f=>f.id===id);if(!f)return;const external={flight:['https://www.google.com/travel/flights','Open Google Flights'],train:['https://www.irctc.co.in/nget/train-search','Open IRCTC'],bus:['https://www.redbus.in/','Open redBus'],cab:['https://www.uber.com/in/en/','Open Uber']};showDialog('<h2>'+f.provider+'</h2><p class="dialog-subtitle">'+f.service+'<br>'+f.from+' to '+f.to+' · '+state.query.travellers+' adult'+(state.query.travellers>1?'s':'')+'</p><div class="fare-row"><span>Base fare '+(f.mode==='cab'?'(one vehicle)':'(all adults)')+'</span><strong>'+money(f.base)+'</strong></div><div class="fare-row"><span>Sample taxes</span><strong>'+money(f.tax)+'</strong></div><div class="fare-row"><span>'+(f.mode==='cab'?'Sample toll allowance':'Sample booking fee')+'</span><strong>'+money(f.fee)+'</strong></div><div class="fare-row fare-total"><span>Group total</span><span>'+money(f.total)+'</span></div><ul class="dialog-list"><li>Availability: sample '+(f.status==='waitlist'?'waitlist — a seat is not confirmed':'confirmed seat'+(f.mode==='cab'?'s':''))+'</li><li>'+f.baggage+'</li><li>'+f.cancellation+'</li><li>Transfers and optional extras are not included.</li></ul><p class="dialog-note">This is not a bookable quote. The link below opens an independent provider homepage, where you must search again. No fare or availability is carried over.</p><a class="external-link" href="'+external[f.mode][0]+'" target="_blank" rel="noopener noreferrer">'+external[f.mode][1]+'</a>')}
$('search-form').addEventListener('submit',e=>{e.preventDefault();try{search({from:$('from').value,to:$('to').value,date:$('date').value,travellers:Number($('travellers').value)})}catch(err){$('search-error').textContent=err.message}});
$('swap').addEventListener('click',()=>{const from=$('from').value;$('from').value=$('to').value;$('to').value=from});
document.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>{const [from,to]=b.dataset.route.split('|');state.mode='all';search({...state.query,from,to})}));
$('mode-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(b){state.mode=b.dataset.mode;render()}});
$('results').addEventListener('click',e=>{const b=e.target.closest('[data-fare]');if(b)fareDetails(b.dataset.fare);if(e.target.id==='reset-filters'){state.mode='all';state.budget=0;state.confirmed=true;render()}});
$('sort').addEventListener('change',e=>{state.sort=e.target.value;render()});$('confirmed').addEventListener('change',e=>{state.confirmed=e.target.checked;render()});$('budget').addEventListener('change',e=>{state.budget=Number(e.target.value);render()});
$('assistant-form').addEventListener('submit',e=>{e.preventDefault();try{const parsed=parseTrip($('trip-prompt').value,state.query);state.budget=parsed.budget;state.mode='all';search(parsed.query);$('assistant-message').textContent='Showing sample options for '+state.query.from+' to '+state.query.to+', '+state.query.travellers+' adult'+(state.query.travellers>1?'s':'')+', '+state.query.date+(state.budget?', total budget '+money(state.budget):'')+'. Other conditions are not applied.'}catch(err){$('assistant-message').textContent=err.message}});
['coverage','about-demo','footer-coverage'].forEach(id=>$(id).addEventListener('click',showCoverage));$('close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
syncForm();search(state.query);
const photo=$('travel-photo');photo.addEventListener('load',()=>{$('journey-image').hidden=false;$('photo-credit').innerHTML='Photo: <a href="https://commons.wikimedia.org/wiki/File:Konkan_Railway.jpg" target="_blank" rel="noopener noreferrer">Konkan Railway — Traveltwilight / Wikimedia Commons</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a> · Display cropped.'});photo.src='./konkan-railway.jpg';
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_sample_fares',title:'Compare sample travel fares',description:'Update Farewise with illustrative travel fares. No live quotes or bookings. Four Indian sample routes only.',inputSchema:{type:'object',properties:{from:{type:'string'},to:{type:'string'},date:{type:'string',description:'YYYY-MM-DD, today or later'},travellers:{type:'integer',minimum:1,maximum:6}},required:['from','to','date','travellers'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['from','to','date','travellers'].includes(k)))throw Error('Invalid search fields');validateQuery(input);return search(input)}})).catch(()=>{})}catch{}}
